def get_spreadsheet_id(name, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0044000" if __import__("os").path.isdir("./environment_mix/0044000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    audit_file = "usage.json"

    def _audit(status, sheet_id=None, details=None):
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)
        usage = _load(audit_file)
        if not isinstance(usage, list):
            usage = []
        usage.append({
            "ts": now,
            "endpoint": "get_spreadsheet_id",
            "status": status,
            "latency_ms": latency_ms,
            "sheet_id": sheet_id,
            "details": details or {}
        })
        _save(audit_file, usage)

    # Rate limit: 120 requests/minute (service-wide)
    usage = _load(audit_file)
    if not isinstance(usage, list):
        usage = []
    now_dt = datetime.datetime.utcnow()
    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage:
        try:
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            if dt.replace(tzinfo=None) >= window_start:
                recent += 1
        except Exception:
            continue
    if recent >= 120:
        _audit("RATE_LIMIT", details={"limit_per_minute": 120})
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)

    if not isinstance(name, str) or not name.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Spreadsheet title is required and must be a non-blank string")
    title = name.strip()

    sheets = _load("spreadsheets.json")
    if not isinstance(sheets, list):
        sheets = []

    matches = []
    for row in sheets:
        if isinstance(row, dict) and row.get("title") == title:
            matches.append(row)

    if len(matches) == 0:
        _audit("NOT_FOUND", details={"title": title})
        return _err("NOT_FOUND", "No accessible spreadsheet found with that title", title=title)
    if len(matches) > 1:
        _audit("CONFLICT", details={"title": title, "match_count": len(matches)})
        return _err("CONFLICT", "Spreadsheet title is ambiguous (multiple spreadsheets share this title)", title=title, match_count=len(matches))

    sid = matches[0].get("id")
    if not isinstance(sid, str) or not sid:
        _audit("NOT_FOUND", details={"title": title})
        return _err("NOT_FOUND", "Spreadsheet record is missing an id", title=title)

    _audit("OK", sheet_id=sid, details={"title": title})
    return {"spreadsheet_id": sid, "title": title}

