def read_values(sheet_id, range_="Sheet1"):
    import json, os
    ss = json.load(open(os.path.join(_DB, "spreadsheets.json"), encoding="utf-8"))
    name, s = None, None
    for nm, sp in ss.items():
        if sp.get("id") == sheet_id or nm == sheet_id:
            name, s = nm, sp; break
    if not s:
        return {"error": f"spreadsheet not found: {sheet_id}"}
    wsname = range_.split("!")[0] if "!" in range_ else range_
    ws = s["worksheets"]
    rows = ws.get(wsname) or next(iter(ws.values()))
    return rows

def update_values(sheet_id, range_, values, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0044000" if __import__("os").path.isdir("./environment_mix/0044000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    audit_file = "usage.json"

    def _audit(status, resolved_sheet_id=None, details=None):
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)
        usage = _load(audit_file)
        if not isinstance(usage, list):
            usage = []
        usage.append({
            "ts": now,
            "endpoint": "update_values",
            "status": status,
            "latency_ms": latency_ms,
            "sheet_id": resolved_sheet_id,
            "details": details or {}
        })
        _save(audit_file, usage)

    # Rate limit: 60 writes/minute (service-wide)
    usage = _load(audit_file)
    if not isinstance(usage, list):
        usage = []
    now_dt = datetime.datetime.utcnow()
    window_start = now_dt - datetime.timedelta(seconds=60)
    recent_writes = 0
    for r in usage:
        try:
            if r.get("endpoint") not in ("update_values", "append_rows", "create_spreadsheet"):
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            if dt.replace(tzinfo=None) >= window_start:
                recent_writes += 1
        except Exception:
            continue
    if recent_writes >= 60:
        _audit("RATE_LIMIT", details={"limit_writes_per_minute": 60})
        return _err("RATE_LIMIT", "Write rate limit exceeded", limit_writes_per_minute=60)

    if not isinstance(sheet_id, str) or not sheet_id.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sheet_id is required and must be a non-blank string")
    if not isinstance(range_, str) or not range_.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "range_ is required and must be a non-blank string")
    if not isinstance(values, list):
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "values must be a 2D array (list of lists of strings)")

    # Validate rectangular 2D
    if len(values) == 0:
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "values must be a non-empty 2D array")
    row_lens = []
    for i, row in enumerate(values):
        if not isinstance(row, list):
            _audit("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "values must be a 2D array (list of lists)", at_row=i)
        row_lens.append(len(row))
        for j, cell in enumerate(row):
            if not isinstance(cell, str):
                _audit("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "All cell values must be strings", at_row=i, at_col=j)
    if len(set(row_lens)) != 1:
        _audit("VALIDATION_ERROR", details={"row_lengths": row_lens})
        return _err("VALIDATION_ERROR", "values must be a rectangular 2D array (all rows same length)", row_lengths=row_lens)

    sheets = _load("spreadsheets.json")
    if not isinstance(sheets, list):
        sheets = []

    # Resolve spreadsheet by id or title
    resolved = None
    for row in sheets:
        if not isinstance(row, dict):
            continue
        if row.get("id") == sheet_id or row.get("title") == sheet_id:
            resolved = row
            break
    if not resolved:
        _audit("NOT_FOUND", details={"sheet_id": sheet_id})
        return _err("NOT_FOUND", "Spreadsheet not found", sheet_id=sheet_id)

    # Parse range_: either "Worksheet" or "Worksheet!A1:C3"
    r = range_.strip()
    if "!" in r:
        ws_name, a1 = r.split("!", 1)
        ws_name = ws_name.strip()
        a1 = a1.strip()
    else:
        ws_name, a1 = r.strip(), None

    if not ws_name:
        _audit("VALIDATION_ERROR", resolved_sheet_id=resolved.get("id"))
        return _err("VALIDATION_ERROR", "Worksheet name could not be resolved from range_", range_=range_)

    worksheets = resolved.get("worksheets")
    if not isinstance(worksheets, dict):
        worksheets = {}
        resolved["worksheets"] = worksheets

    # If A1 is specified, enforce that it is a simple A1[:B2] and fits dimensions; apply into existing grid.
    def _col_to_idx(col):
        n = 0
        for ch in col:
            if not ("A" <= ch <= "Z"):
                return None
            n = n * 26 + (ord(ch) - ord("A") + 1)
        return n - 1  # 0-based

    def _parse_a1(a1s):
        m = re.fullmatch(r"([A-Za-z]+)(\d+)(?::([A-Za-z]+)(\d+))?", a1s)
        if not m:
            return None
        c1, r1, c2, r2 = m.group(1), m.group(2), m.group(3), m.group(4)
        c1i = _col_to_idx(c1.upper())
        if c1i is None:
            return None
        r1i = int(r1) - 1
        if r1i < 0:
            return None
        if c2 is None:
            return (r1i, c1i, r1i, c1i)
        c2i = _col_to_idx(c2.upper())
        r2i = int(r2) - 1
        if c2i is None or r2i < 0:
            return None
        # normalize
        rmin, rmax = (r1i, r2i) if r1i <= r2i else (r2i, r1i)
        cmin, cmax = (c1i, c2i) if c1i <= c2i else (c2i, c1i)
        return (rmin, cmin, rmax, cmax)

    if a1 is None or a1 == "":
        # Replace whole worksheet values
        worksheets[ws_name] = values
        resolved["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("spreadsheets.json", sheets)
        _audit("OK", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name, "mode": "replace_sheet"})
        return {
            "spreadsheet_id": resolved.get("id"),
            "range": ws_name,
            "updated_range": ws_name,
            "values": worksheets[ws_name],
            "updated_rows": len(values),
            "updated_columns": row_lens[0]
        }

    parsed = _parse_a1(a1)
    if parsed is None:
        _audit("VALIDATION_ERROR", resolved_sheet_id=resolved.get("id"), details={"range_": range_})
        return _err("VALIDATION_ERROR", "Unsupported or invalid A1 notation in range_", range_=range_)

    rmin, cmin, rmax, cmax = parsed
    target_rows = (rmax - rmin + 1)
    target_cols = (cmax - cmin + 1)
    if target_rows != len(values) or target_cols != row_lens[0]:
        _audit("VALIDATION_ERROR", resolved_sheet_id=resolved.get("id"), details={"target_rows": target_rows, "target_cols": target_cols})
        return _err(
            "VALIDATION_ERROR",
            "values dimensions do not match the target A1 range",
            target_rows=target_rows,
            target_cols=target_cols,
            values_rows=len(values),
            values_cols=row_lens[0],
        )

    grid = worksheets.get(ws_name, [])
    if not isinstance(grid, list):
        grid = []
    # ensure grid size
    needed_rows = rmax + 1
    needed_cols = cmax + 1
    while len(grid) < needed_rows:
        grid.append([])
    for rr in range(len(grid)):
        if not isinstance(grid[rr], list):
            grid[rr] = []
        if len(grid[rr]) < needed_cols:
            grid[rr].extend([""] * (needed_cols - len(grid[rr])))

    # apply
    for i in range(target_rows):
        for j in range(target_cols):
            grid[rmin + i][cmin + j] = values[i][j]

    worksheets[ws_name] = grid
    resolved["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("spreadsheets.json", sheets)
    _audit("OK", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name, "mode": "a1_update", "a1": a1})

    updated_a1 = f"{ws_name}!{a1}"
    return {
        "spreadsheet_id": resolved.get("id"),
        "range": updated_a1,
        "updated_range": updated_a1,
        "values": values,
        "updated_rows": len(values),
        "updated_columns": row_lens[0],
    }

