                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            if dt.replace(tzinfo=None) >= window_start:
                recent_writes += 1
        except Exception:
            continue
    if recent_writes >= 60:
        _audit("RATE_LIMIT", details={"limit_writes_per_minute": 60})
        return _err("RATE_LIMIT", "Write rate limit exceeded", limit_writes_per_minute=60)

    if not isinstance(sheet_id, str) or not sheet_id.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sheet_id is required and must be a non-blank string")
    if worksheet is None:
        worksheet = "Sheet1"
    if not isinstance(worksheet, str) or not worksheet.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "worksheet must be a non-blank string")
    if not isinstance(values, list) or len(values) == 0:
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "values must be a non-empty 2D array of rows")

    # Normalize: if a single row provided as list[str] (not list[list])
    if values and (not isinstance(values[0], list)):
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "values must be a 2D array (list of rows); got 1D array")

    for i, row in enumerate(values):
        if not isinstance(row, list):
            _audit("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "values must be a 2D array (list of lists)", at_row=i)
        for j, cell in enumerate(row):
            if not isinstance(cell, str):
                _audit("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "All cell values must be strings", at_row=i, at_col=j)

    sheets = _load("spreadsheets.json")
    if not isinstance(sheets, list):
        sheets = []

    resolved = None
    for row in sheets:
        if not isinstance(row, dict):
            continue
        if row.get("id") == sheet_id or row.get("title") == sheet_id:
            resolved = row
            break
    if not resolved:
        _audit("NOT_FOUND", details={"sheet_id": sheet_id})
        return _err("NOT_FOUND", "Spreadsheet not found", sheet_id=sheet_id)

    ws_name = worksheet.strip()
    worksheets = resolved.get("worksheets")
    if not isinstance(worksheets, dict):
        worksheets = {}
        resolved["worksheets"] = worksheets

    ws = worksheets.get(ws_name)
    if ws is None:
        ws = []
        worksheets[ws_name] = ws
    if not isinstance(ws, list):
        _audit("CONFLICT", resolved_sheet_id=resolved.get("id"))
        return _err("CONFLICT", "Worksheet storage is corrupted (expected array of rows)", worksheet=ws_name)

    start_row = len(ws) + 1  # 1-based
    ws.extend(values)
    end_row = len(ws)

    resolved["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("spreadsheets.json", sheets)
    _audit("OK", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name, "appended": len(values)})

    return {
        "spreadsheet_id": resolved.get("id"),
        "worksheet": ws_name,
        "updates": {
            "appended_rows": len(values),
            "table_range": f"{ws_name}!A{start_row}",
            "start_row": start_row,
            "end_row": end_row
        }
    }

def create_spreadsheet(title, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0044000" if __import__("os").path.isdir("./environment_mix/0044000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    audit_file = "usage.json"

    def _audit(status, resolved_sheet_id=None, details=None):
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)
        usage = _load(audit_file)
        if not isinstance(usage, list):
            usage = []
        usage.append({
            "ts": now,
            "endpoint": "create_spreadsheet",
            "status": status,
            "latency_ms": latency_ms,
            "sheet_id": resolved_sheet_id,
            "details": details or {}
        })
        _save(audit_file, usage)

    # Rate limit: 60 writes/minute (service-wide)
    usage = _load(audit_file)
    if not isinstance(usage, list):
        usage = []
    now_dt = datetime.datetime.utcnow()
    window_start = now_dt - datetime.timedelta(seconds=60)
    recent_writes = 0
    for r in usage:
        try:
            if r.get("endpoint") not in ("update_values", "append_rows", "create_spreadsheet"):
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            if dt.replace(tzinfo=None) >= window_start:
                recent_writes += 1
        except Exception:
            continue
    if recent_writes >= 60:
        _audit("RATE_LIMIT", details={"limit_writes_per_minute": 60})
        return _err("RATE_LIMIT", "Write rate limit exceeded", limit_writes_per_minute=60)

    if not isinstance(title, str) or not title.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is required and must be a non-blank string")

    title = title.strip()
    if len(title) > 100:
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is too long (max 100 characters)", max_len=100)
    if any(ch in title for ch in ["\n", "\r", "\t"]):
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title contains invalid control characters")

    sheets = _load("spreadsheets.json")
    if not isinstance(sheets, list):
        sheets = []

    # Idempotent create by title: if exists, return existing
    for row in sheets:
        if isinstance(row, dict) and row.get("title") == title and isinstance(row.get("id"), str) and row.get("id"):
            sid = row["id"]
            _audit("OK", resolved_sheet_id=sid, details={"created": False, "title": title})
            return {"spreadsheet_id": sid, "title": title, "created": False}

    # Generate a unique id (must be one of allowed enums in schema)
    allowed = ["sheet_capa", "sheet_dt", "sheet_fc", "sheet_inv", "sheet_ps", "sheet_q1cb", "sheet_ss"]
    used = set()
    for row in sheets:
        if isinstance(row, dict) and isinstance(row.get("id"), str):
            used.add(row["id"])
    chosen = None
    # Prefer deterministic choice based on title but ensure uniqueness
    h = int(hashlib.sha256(title.encode("utf-8")).hexdigest(), 16)
    for k in range(len(allowed)):
        cand = allowed[(h + k) % len(allowed)]
        if cand not in used:
            chosen = cand
            break
    if chosen is None:
        _audit("CONFLICT", details={"reason": "no_available_ids"})
        return _err("CONFLICT", "No available spreadsheet ids remain in this service")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    new_row = {
        "id": chosen,
        "title": title,
        "worksheets": {"Sheet1": []},
        "created_at": now,
        "updated_at": now
    }
    sheets.append(new_row)
    _save("spreadsheets.json", sheets)
    _audit("OK", resolved_sheet_id=chosen, details={"created": True, "title": title})

    return {"spreadsheet_id": chosen, "title": title, "created": True}

