        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)

    if not isinstance(sheet_id, str) or not sheet_id.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sheet_id is required and must be a non-blank string")
    if not isinstance(worksheet, str) or not worksheet.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "worksheet is required and must be a non-blank string")
    if not isinstance(column, str) or not column.strip():
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "column is required and must be a non-blank string")
    if not isinstance(value, str):
        _audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "value must be a string")

    sheets = _load("spreadsheets.json")
    if not isinstance(sheets, list):
        sheets = []

    resolved = None
    for row in sheets:
        if not isinstance(row, dict):
            continue
        if row.get("id") == sheet_id or row.get("title") == sheet_id:
            resolved = row
            break
    if not resolved:
        _audit("NOT_FOUND", details={"sheet_id": sheet_id})
        return _err("NOT_FOUND", "Spreadsheet not found", sheet_id=sheet_id)

    ws_name = worksheet.strip()
    worksheets = resolved.get("worksheets")
    if not isinstance(worksheets, dict):
        _audit("CONFLICT", resolved_sheet_id=resolved.get("id"))
        return _err("CONFLICT", "Spreadsheet worksheets are corrupted (expected object/dict)")

    rows = worksheets.get(ws_name)
    if rows is None:
        _audit("NOT_FOUND", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name})
        return _err("NOT_FOUND", "Worksheet not found", worksheet=ws_name)
    if not isinstance(rows, list):
        _audit("CONFLICT", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name})
        return _err("CONFLICT", "Worksheet content is corrupted (expected array of rows)", worksheet=ws_name)

    if len(rows) == 0:
        _audit("OK", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name, "found": False})
        return {"found": False, "row_number": None, "row": None}

    header = rows[0]
    if not isinstance(header, list):
        _audit("CONFLICT", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name})
        return _err("CONFLICT", "Header row is corrupted (expected array)", worksheet=ws_name)

    # header must contain column exactly once
    indices = [i for i, h in enumerate(header) if str(h) == column]
    if len(indices) == 0:
        _audit("VALIDATION_ERROR", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name, "column": column})
        return _err("VALIDATION_ERROR", "Header column does not exist", worksheet=ws_name, column=column)
    if len(indices) > 1:
        _audit("CONFLICT", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name, "column": column, "count": len(indices)})
        return _err("CONFLICT", "Header column is ambiguous (duplicate headers)", worksheet=ws_name, column=column, count=len(indices))
    cidx = indices[0]

    target = str(value)
    for i, r in enumerate(rows[1:], start=2):  # 1-based row numbers; header is row 1
        if not isinstance(r, list):
            continue
        cell = str(r[cidx]) if cidx < len(r) else ""
        if cell == target:
            _audit("OK", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name, "found": True, "row_number": i})
            return {"found": True, "row_number": i, "row": r}

    _audit("OK", resolved_sheet_id=resolved.get("id"), details={"worksheet": ws_name, "found": False})
    return {"found": False, "row_number": None, "row": None}
